39	    uint32 internal constant VRF_CALLBACK_GAS_LIMIT = 300_000;
40	
41	    /// @notice Block confirmations requested from Chainlink before callback fulfillment.
42	    uint16 internal constant VRF_REQUEST_CONFIRMATIONS = 30;
43	}

